mapper.update:
UPDATE cover_letter
SET
	title			= #{title}
	, industry_idx	= (SELECT industry_idx FROM industry WHERE industry_code = #{industryCode})
	, job_idx		= (SELECT job_idx FROM job_group WHERE job_code = #{jobCode})
	, role_idx		= (SELECT role_idx FROM job_role WHERE role_code = #{roleCode})
	, applied_field = #{appliedField}
	, company_name 	= #{companyName}
	, company_idx	= (SELECT company_idx FROM company_type WHERE company_code = #{companyCode})
	, career_idx	= (SELECT career_idx FROM career_level WHERE career_code = #{careerCode})
	, save_status	= #{saveStatus}
WHERE cover_letter_idx = #{coverLetterIdx}
	AND user_id = #{userId}

UPDATE cover_letter
SET 
	question_idx = (SELECT 	question_idx
					FROM 	question_category
					WHERE 	question_code = #{questionCode})
	, content = #{content}
	, save_status = #{saveStatus}
	, ai_generated = #{aiGenerated} 
WHERE cover_letter_idx = #{coverLetterIdx}
